const steps = ["personal", "employment", "loan", "review"];
function next() {
 if (!isValid(steps[step], application[steps[step]])) return;
 setStep(s => Math.min(s + 1, steps.length - 1));
}
function update(section, values) {
 setApplication(a => ({...a, [section]: {...a[section], ...values}}));
}
// Final step: submit application once all sections pass validation.`,explain:"Keep all sections in a parent state so moving between steps does not lose input. Validate on both client and server."},{n:27,level:"Hard",area:"React",title:"API pagination, search and sorting",prompt:"Combine search, category filter, price sort and pagination. Why filter before paginate?",answer:"Page only the matching, sorted result set",code:`const filtered = products
